 {view==='docs'&&<div className="listpage"><div className="sectionhead"><div><h2>資料・データ</h2><p>{selected?.title||'イベントを選択してください'}</p></div><button onClick={exportCsv}>イベント一覧CSV</button></div>{selected&&<><label className="uploadbtn">＋ 資料・フライヤーをアップロード<input type="file" hidden onChange={uploadDoc}/></label>{docs.map(d=><button className="listrow" key={d.id} onClick={()=>openDoc(d)}><b>{d.name}</b><span>{d.content_type||'ファイル'}</span><small>{new Date(d.created_at).toLocaleString('ja-JP')}</small></button>)}</>}</div>}
 {view==='team'&&<div className="listpage"><div className="sectionhead"><div><h2>チーム</h2><p>{team?.name} / あなたの権限: {team?.role==='owner'?'オーナー':'メンバー'}</p></div>{team?.role==='owner'&&<button className="primary" onClick={()=>setModal('invite')}>＋ スタッフ招待</button>}</div><h3>スタッフ権限</h3><p className="hint">制作スタッフは編集可能、閲覧のみはデータを見るだけです。</p>{members.filter(m=>m.role!=='owner').map(m=><div className="listrow" key={m.user_id}><b>スタッフ</b><span>{m.user_id.slice(0,8)}…</span>{team?.role==='owner'?<select value={m.role} onChange={e=>changeRole(m,e.target.value)}><option value="member">制作スタッフ</option><option value="viewer">閲覧のみ</option></select>:<small>{m.role}</small>}</div>)}<h3>招待</h3>{invites.length?invites.map(i=><div className="team-invite-card" key={i.id}><div className="team-invite-main"><b>{i.email}</b><span className={'team-invite-badge '+(i.accepted_at?'accepted':'pending')}>{i.accepted_at?'参加済み':'招待中'}</span></div>{!i.accepted_at&&i.email.toLowerCase()===session.user.email?.toLowerCase()&&<button className="team-invite-action" onClick={()=>acceptInvite(i)}>このチームに参加</button>}</div>):<p>招待はありません。</p>}</div>}
